def select_node(pod: dict, feasible_nodes: list[dict], state: dict) -> int:
    """
    Choose a node for the given pod with the aim of minimizing node activation/deactivation churn.
    Prefer already‑active nodes that host many pods (high placed_pods_count). If no active node can
    accommodate the pod, pick the cheapest idle node (lowest cost_per_hour) with the most remaining
    capacity to reduce future activation cost.
    """
    # Guard against empty feasible_nodes (should not happen in normal operation)
    if not feasible_nodes:
        return None  # type: ignore[return-value]

    # Pre‑compute active node set for O(1) look‑ups
    active_set = set(state.get('active_node_ids', []))

    # Helper to safely fetch placement count and remaining resources
    def placed_count(node_id):
        return state.get('placed_pods_count', {}).get(node_id, 0)

    def remaining_cpu(node_id):
        return state.get('remaining_cpu', {}).get(
            node_id,
            feasible_nodes[0].get('cpu_capacity', 0.0)  # fallback, will be overridden per node
        )

    def remaining_mem(node_id):
        return state.get('remaining_mem', {}).get(
            node_id,
            feasible_nodes[0].get('mem_capacity', 0.0)
        )

    # Separate active and idle feasible nodes
    active_nodes = [n for n in feasible_nodes if n.get('id') in active_set]

    if active_nodes:
        # Choose active node with highest placed_pods_count; break ties by lower cost
        best = max(
            active_nodes,
            key=lambda n: (
                placed_count(n.get('id')),
                -n.get('cost_per_hour', float('inf'))
            )
        )
        return best.get('id')
    else:
        # No active feasible node: activate the cheapest idle node with most remaining capacity
        def total_remain(n):
            nid = n.get('id')
            return remaining_cpu(nid) + remaining_mem(nid)

        best = min(
            feasible_nodes,
            key=lambda n: (
                n.get('cost_per_hour', float('inf')),
                -total_remain(n)
            )
        )
        return best.get('id')


def select_pod(pending_pods: list[dict], nodes: list[dict], state: dict) -> int:
    """
    Optional heuristic to pick which pending pod to schedule first.
    Prefers pods with larger resource demand and/or longer known duration,
    aiming to fill active nodes quickly and reduce churn.
    """
    if not pending_pods:
        return 0  # arbitrary, caller should handle empty list

    def pod_score(p):
        cpu = p.get('cpu', 0.0)
        mem = p.get('mem', 0.0)
        dur = p.get('duration_sec', 3600.0)  # default 1 hour if unknown
        # Convert duration to hours to keep scale comparable to CPU+Mem
        return cpu + mem + dur / 3600.0

    # Return index of the pod with the highest score
    return max(range(len(pending_pods)), key=lambda i: pod_score(pending_pods[i]))
